// Finds the uploaded file (whatever the form field is called) and normalises it to binary "data".
const item = $input.first();
const j = item.json;
const get = (k) => (j[k] !== undefined && j[k] !== null) ? String(j[k]).trim() : '';
const out = {
  supplierName: get('Supplier Name'),
  country: get('Country of Origin'),
  details: get('Additional Details'),
  submitterEmail: get('Submitter Email'),
  submittedAt: new Date().toISOString(),
  ext: 'none', fileName: '', mimeType: ''
};
const bin = item.binary || {};
const keys = Object.keys(bin);
const result = { json: out };
if (keys.length) {
  const b = bin[keys[0]];
  const name = String(b.fileName || '').toLowerCase();
  const mime = String(b.mimeType || '').toLowerCase();
  let ext = name.includes('.') ? name.split('.').pop() : '';
  if (!ext) { if (mime.includes('pdf')) ext = 'pdf'; else if (mime.includes('csv')) ext = 'csv'; }
  out.ext = ext; out.fileName = b.fileName || ''; out.mimeType = b.mimeType || '';
  result.binary = { data: b };
}
return [result];

// Scores the submission. CSV = one score per row (case score = highest). PDF = whole text. Text-only = form fields.
// !! WATCHLIST below is a DEMO list. Replace it with the official DHS UFLPA Entity List before real use.
const meta = $('Detect File').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);

const WATCHLIST = ['hoshine silicon','xinjiang daqo','xinjiang production and construction corps','xpcc','changji esquel','xinjiang gcl'];
const REGION_RE = /\b(xinjiang|xuar|uyghur|uighur|east turkestan|kashgar|hotan|aksu|turpan|urumqi|shihezi|korla|karamay|changji)\b/i;
const COMMODITY_RE = /\b(cotton|tomato(es)?|polysilicon|silicon|pvc|aluminum|aluminium|seafood|textiles?|apparel|viscose)\b/i;
const GAP_RE = /(unknown origin|origin unknown|unverified|no documentation|not traceable|subcontract|third[- ]party sourced)/i;
const CHINA_RE = /\b(china|prc|cn)\b/i;

function score(text, country){
  let s = 0; const flags = []; const t = String(text || '');
  for (const w of WATCHLIST) {
    const re = new RegExp('\\b' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
    if (re.test(t)) { s += 60; flags.push('Watchlist match: ' + w); }
  }
  if (REGION_RE.test(t)) { s += 45; flags.push('Xinjiang / high-risk region reference'); }
  if (COMMODITY_RE.test(t)) { s += 15; flags.push('UFLPA high-priority commodity'); }
  if (GAP_RE.test(t)) { s += 10; flags.push('Traceability gap language'); }
  if (CHINA_RE.test(String(country || ''))) { s += 10; flags.push('Origin: China'); }
  return { score: Math.min(100, s), flags };
}

const base = score([meta.supplierName, meta.details].join(' | '), meta.country);
let max = base.score;
const allFlags = new Set(base.flags);
const findings = [];
let rowCount = 0, pages = 0;

if (meta.ext === 'csv') {
  rowCount = rows.length;
  for (const r of rows) {
    const keys = Object.keys(r);
    const nameKey = keys.find(k => /supplier|vendor|company|name/i.test(k));
    const ctryKey = keys.find(k => /country|origin|region/i.test(k));
    const res = score(Object.values(r).join(' | '), ctryKey ? r[ctryKey] : '');
    if (res.score > 0) {
      findings.push({ entity: nameKey ? String(r[nameKey]) : '(row)', score: res.score, flags: res.flags });
      res.flags.forEach(f => allFlags.add(f));
      max = Math.max(max, res.score);
    }
  }
} else if (meta.ext === 'pdf') {
  const text = rows[0] && rows[0].text ? String(rows[0].text) : '';
  pages = rows[0] && rows[0].numpages ? rows[0].numpages : 0;
  const res = score(text, meta.country);
  if (res.score > 0) {
    findings.push({ entity: 'PDF: ' + meta.fileName, score: res.score, flags: res.flags });
    res.flags.forEach(f => allFlags.add(f));
    max = Math.max(max, res.score);
  }
}
findings.sort((a, b) => b.score - a.score);
const riskLevel = max >= 70 ? 'HIGH' : max >= 40 ? 'MEDIUM' : 'LOW';
return [{ json: {
  ...meta, rowCount, pages,
  findings: findings.slice(0, 25), findingsTotal: findings.length,
  flags: Array.from(allFlags), score: max, riskLevel,
  needsReview: max >= 40
} }];

function sha256(ascii){
  function rightRotate(v,a){return (v>>>a)|(v<<(32-a));}
  var maxWord=Math.pow(2,32), result='', words=[], asciiBitLength=ascii.length*8;
  var hash=[], k=[], primeCounter=0, isComposite={};
  for(var candidate=2;primeCounter<64;candidate++){
    if(!isComposite[candidate]){
      for(var i=0;i<313;i+=candidate) isComposite[i]=candidate;
      hash[primeCounter]=(Math.pow(candidate,.5)*maxWord)|0;
      k[primeCounter++]=(Math.pow(candidate,1/3)*maxWord)|0;
    }
  }
  ascii+='\x80';
  while(ascii.length%64-56) ascii+='\x00';
  for(var i=0;i<ascii.length;i++){
    var j=ascii.charCodeAt(i);
    if(j>>8) return;
    words[i>>2]|=j<<((3-i)%4)*8;
  }
  words[words.length]=((asciiBitLength/maxWord)|0);
  words[words.length]=(asciiBitLength);
  for(var j=0;j<words.length;){
    var w=words.slice(j,j+=16);
    var oldHash=hash;
    hash=hash.slice(0,8);
    for(var i=0;i<64;i++){
      var w15=w[i-15], w2=w[i-2];
      var a=hash[0], e=hash[4];
      var temp1=hash[7]+(rightRotate(e,6)^rightRotate(e,11)^rightRotate(e,25))+((e&hash[5])^((~e)&hash[6]))+k[i]+(w[i]=(i<16)?w[i]:(w[i-16]+(rightRotate(w15,7)^rightRotate(w15,18)^(w15>>>3))+w[i-7]+(rightRotate(w2,17)^rightRotate(w2,19)^(w2>>>10)))|0);
      var temp2=(rightRotate(a,2)^rightRotate(a,13)^rightRotate(a,22))+((a&hash[1])^(a&hash[2])^(hash[1]&hash[2]));
      hash=[(temp1+temp2)|0].concat(hash);
      hash[4]=(hash[4]+temp1)|0;
    }
    for(var i=0;i<8;i++) hash[i]=(hash[i]+oldHash[i])|0;
  }
  for(var i=0;i<8;i++) for(var j=3;j+1;j--){var b=(hash[i]>>(j*8))&255; result+=((b<16)?0:'')+b.toString(16);}
  return result;
}

const GENESIS = '0'.repeat(64);
function hashEntry(e){
  const s = [e.prevHash, e.seq, e.ts, e.caseId, e.action, e.actor, e.detail, JSON.stringify(e.data || null)].join('|');
  return sha256(unescape(encodeURIComponent(s)));
}
function readEvents(rows){
  const ev = [];
  for (const r of rows) {
    const p = r.json && r.json.payload;
    if (!p) continue;
    try { ev.push(JSON.parse(p)); } catch (x) {}
  }
  ev.sort((a, b) => a.seq - b.seq);
  return ev;
}
function makeEvent(events, o){
  const prev = events.length ? events[events.length - 1] : null;
  const e = { seq: (prev ? prev.seq : 0) + 1, ts: new Date().toISOString(), caseId: o.caseId, action: o.action, actor: o.actor, detail: String(o.detail || ''), prevHash: prev ? prev.hash : GENESIS, data: o.data || null };
  e.hash = hashEntry(e);
  events.push(e);
  return e;
}

const events = readEvents($input.all());
const d = $('Attach Review URL').first().json;
const caseId = 'TG-' + $execution.id;
const review = !!d.needsReview;
const now = new Date().toISOString();
const snap = {
  caseId, supplier: d.supplierName || '(unnamed)', country: d.country || '',
  score: d.score, riskLevel: d.riskLevel, flags: d.flags || [], findingsTotal: d.findingsTotal || 0,
  fileName: d.fileName || '', submitterEmail: d.submitterEmail || '',
  status: review ? 'pending' : 'auto_approved', reviewUrl: review ? (d.reviewUrl || '') : '',
  decision: review ? '' : 'approved', decidedBy: review ? '' : 'system (auto)', justification: '',
  createdAt: now, decidedAt: review ? '' : now
};
const out = [];
out.push(makeEvent(events, { caseId, action: 'SUBMITTED', actor: 'intake-form', detail: 'score ' + d.score + ' (' + d.riskLevel + ') file=' + (d.fileName || 'none'), data: snap }));
if (review) out.push(makeEvent(events, { caseId, action: 'SENT_TO_REVIEW', actor: 'system', detail: 'awaiting compliance officer', data: { status: 'pending' } }));
else out.push(makeEvent(events, { caseId, action: 'AUTO_APPROVED', actor: 'system', detail: 'score below review threshold', data: { status: 'auto_approved', decision: 'approved', decidedBy: 'system (auto)', decidedAt: now } }));
return out.map(e => ({ json: { payload: JSON.stringify(e) } }));

