const events = readEvents($input.all());
const f = $('Human Review (Wait)').first().json;
const caseId = 'TG-' + $execution.id;
const decision = String(f['Decision'] || '').toLowerCase().startsWith('b') ? 'blocked' : 'approved';
const reviewer = String(f['Reviewer Name'] || 'unknown');
const why = String(f['Justification'] || '');
const e = makeEvent(events, { caseId, action: decision === 'blocked' ? 'BLOCKED' : 'APPROVED', actor: reviewer, detail: why.slice(0, 200),
  data: { status: decision, decision, decidedBy: reviewer, justification: why, decidedAt: new Date().toISOString(), reviewUrl: '' } });
return [{ json: { payload: JSON.stringify(e) } }];

