const events = readEvents($input.all());
const cMap = {};
for (const e of events) { if (e.data) cMap[e.caseId] = Object.assign(cMap[e.caseId] || { caseId: e.caseId }, e.data); }
const sd = { log: events };
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cases = Object.values(cMap).sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
const pending = cases.filter(c => c.status === 'pending');
let intact = true, brokenAt = null;
sd.log.forEach((e, i) => {
  const bad = hashEntry(e) !== e.hash || (i > 0 && e.prevHash !== sd.log[i-1].hash);
  if (bad && intact) { intact = false; brokenAt = e.seq; }
});
const badge = l => '<span class="b ' + esc(String(l).toLowerCase()) + '">' + esc(l || '-') + '</span>';
const stat = (c, s) => cases.filter(x => x.status === s).length;
const pendRows = pending.map(c => {
  const link = /^https?:\/\//.test(c.reviewUrl || '') ? '<a class="btn" target="_blank" rel="noopener" href="' + esc(c.reviewUrl) + '">Review &rarr;</a>' : 'n/a';
  return '<tr><td>' + esc(c.caseId) + '</td><td>' + esc(c.supplier) + '</td><td>' + esc(c.country) + '</td><td>' + esc(c.score) + '</td><td>' + badge(c.riskLevel) + '</td><td>' + esc((c.flags || []).join('; ')) + '</td><td>' + link + '</td></tr>';
}).join('');
const caseRows = cases.map(c => '<tr><td>' + esc(c.caseId) + '</td><td>' + esc(c.supplier) + '</td><td>' + esc(c.score) + '</td><td>' + badge(c.riskLevel) + '</td><td>' + esc(c.status) + '</td><td>' + esc(c.decidedBy || '') + '</td><td>' + esc((c.createdAt || '').slice(0, 19).replace('T', ' ')) + '</td></tr>').join('');
const logRows = sd.log.slice().reverse().slice(0, 100).map(e => '<tr><td>' + esc(e.seq) + '</td><td>' + esc(e.ts.slice(0, 19).replace('T', ' ')) + '</td><td>' + esc(e.caseId) + '</td><td>' + esc(e.action) + '</td><td>' + esc(e.actor) + '</td><td class="h">' + esc(e.hash.slice(0, 16)) + '&hellip;</td><td class="h">' + esc(e.prevHash.slice(0, 16)) + '&hellip;</td></tr>').join('');
const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="20"><title>TraceGuard Review Queue</title><style>' +
 'body{font-family:system-ui,Segoe UI,Arial,sans-serif;margin:0;background:#0f172a;color:#e2e8f0}header{padding:20px 28px;background:#111c3a;border-bottom:1px solid #1e293b}h1{margin:0;font-size:22px}h2{margin:28px 0 10px;font-size:16px;color:#93c5fd}main{padding:0 28px 40px}' +
 '.cards{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}.card{background:#1e293b;border-radius:10px;padding:12px 18px;min-width:120px}.card b{display:block;font-size:24px}' +
 'table{width:100%;border-collapse:collapse;background:#1e293b;border-radius:8px;overflow:hidden;font-size:13px}th,td{padding:8px 10px;text-align:left;border-bottom:1px solid #334155;vertical-align:top}th{background:#273449;color:#94a3b8}' +
 '.b{padding:2px 8px;border-radius:99px;font-size:11px;font-weight:700}.high{background:#7f1d1d;color:#fecaca}.medium{background:#78350f;color:#fde68a}.low{background:#14532d;color:#bbf7d0}' +
 '.btn{background:#2563eb;color:#fff;padding:4px 10px;border-radius:6px;text-decoration:none}.h{font-family:monospace;color:#94a3b8}.ok{color:#4ade80}.bad{color:#f87171}.muted{color:#64748b;font-size:12px}</style></head><body>' +
 '<header><h1>TraceGuard &mdash; UFLPA Review Queue</h1><div class="muted">Auto-refreshes every 20s &middot; generated ' + esc(new Date().toISOString().slice(0, 19).replace('T', ' ')) + ' UTC &middot; ' + events.length + ' log events loaded</div></header><main>' +
 '<div class="cards"><div class="card"><b>' + pending.length + '</b>Pending review</div><div class="card"><b>' + stat(0, 'approved') + '</b>Approved</div><div class="card"><b>' + stat(0, 'blocked') + '</b>Blocked</div><div class="card"><b>' + stat(0, 'auto_approved') + '</b>Auto-approved</div>' +
 '<div class="card"><b class="' + (intact ? 'ok' : 'bad') + '">' + (intact ? 'INTACT' : 'BROKEN @' + brokenAt) + '</b>Decision-log hash chain</div></div>' +
 '<h2>Pending human review</h2><table><tr><th>Case</th><th>Supplier</th><th>Country</th><th>Score</th><th>Risk</th><th>Flags</th><th>Action</th></tr>' + (pendRows || '<tr><td colspan="7">Nothing pending.</td></tr>') + '</table>' +
 '<h2>All cases</h2><table><tr><th>Case</th><th>Supplier</th><th>Score</th><th>Risk</th><th>Status</th><th>Decided by</th><th>Created (UTC)</th></tr>' + (caseRows || '<tr><td colspan="7">No cases yet.</td></tr>') + '</table>' +
